# Builds the starter stages (Docs/ADR/0024-startup-atmospheres-starter-stages.md Â§6) into Content/StageCraft/Templates.
#
# Each stage is built in a scripted -game run through the app's own paths: Sketch to Stage strokes (decks, truss, fixtures)
# generated by StageCraft.Sketch.Generate (the controller's build-plan request), an atmosphere preset, then StageCraft.Scene.Save.
# So every item's saved state is what the real spawn path writes; nothing in the JSON is hand-made. The files are then copied
# into the Templates folder and the user's own data is restored (Scripts/Tests/RunGameScripted.ps1).
#
#   powershell -ExecutionPolicy Bypass -File Scripts\Content\build_starter_stages.ps1     (the editor must be closed)
#
# The audience is on -X; x and y are in metres; -ExecCmds splits on commas, so points are written x:y.
# Truss points snap to the 2 m section length: draw truss lines on even metres, and fixtures on them, or the fixtures stand on the floor.
$ErrorActionPreference = 'Stop'
$Root = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$Templates = Join-Path $Root 'Content\StageCraft\Templates'

function Stage([double]$At, [string]$Name, [string[]]$Build, [string[]]$Environment) {
	$Steps = @("$At StageCraft.Edit.ClearStage confirm", "$($At + 0.2) StageCraft.Sketch.Clear")
	$T = $At + 0.4
	foreach ($Command in $Build) { $Steps += "$T $Command"; $T += 0.1 }
	if ($Build.Count -gt 0) { $Steps += "$($T + 0.5) StageCraft.Sketch.Generate" }
	$T += 1.5
	foreach ($Command in $Environment) { $Steps += "$T $Command"; $T += 0.1 }
	# The atmosphere blends over 2 s; the stored settings are already the new ones, so saving after it is only for the screenshot.
	$Steps += "$($T + 2.5) StageCraft.Scene.Save $Name"
	$Steps += "$($T + 2.8) StageCraft.Workspace.Screenshot"
	return ,$Steps
}

# Neutral camera look for the venue's own lighting (the theatre).
$VenueLook = @('StageCraft.Environment.Set Lighting Level', 'StageCraft.Environment.Set Exposure 0', 'StageCraft.Environment.Set Bloom 0.675', 'StageCraft.Environment.Set WhiteBalance 6500')

$Steps = @('3 StageCraft.Workspace.OpenPanel StageCraft.Panel.Environment')

# Concert: a 12 x 8 m main deck at 1.2 m with a thrust into the audience, a front and a back truss at 7 m, moving lights.
$Steps += Stage 5 'Concert' @(
	'StageCraft.Sketch.Set DeckHeight 120', 'StageCraft.Sketch.Set TrussHeight 700',
	'StageCraft.Sketch.Add Shape -4:-6 4:-6 4:6 -4:6 closed',
	'StageCraft.Sketch.Add Shape -8:-1.5 -4:-1.5 -4:1.5 -8:1.5 closed',
	'StageCraft.Sketch.Add Truss -6:-8 -6:8',
	'StageCraft.Sketch.Add Truss 4:-8 4:8',
	'StageCraft.Sketch.Add Fixture -6:-6', 'StageCraft.Sketch.Add Fixture -6:-3', 'StageCraft.Sketch.Add Fixture -6:0',
	'StageCraft.Sketch.Add Fixture -6:3', 'StageCraft.Sketch.Add Fixture -6:6',
	'StageCraft.Sketch.Add Fixture 4:-5', 'StageCraft.Sketch.Add Fixture 4:-2', 'StageCraft.Sketch.Add Fixture 4:2', 'StageCraft.Sketch.Add Fixture 4:5'
) @('StageCraft.Environment.Atmosphere Cyberpunk Night')

# Theatre: a 6 x 10 m proscenium deck at 0.9 m and three lighting bars at 6.5 m, in the venue's own lighting.
$Steps += Stage 20 'Theatre' @(
	'StageCraft.Sketch.Set DeckHeight 90', 'StageCraft.Sketch.Set TrussHeight 650',
	'StageCraft.Sketch.Add Shape -3:-5 3:-5 3:5 -3:5 closed',
	'StageCraft.Sketch.Add Truss -4:-6 -4:6', 'StageCraft.Sketch.Add Truss 0:-6 0:6', 'StageCraft.Sketch.Add Truss 2:-6 2:6',
	'StageCraft.Sketch.Add Fixture -4:-4', 'StageCraft.Sketch.Add Fixture -4:-1.5', 'StageCraft.Sketch.Add Fixture -4:1.5', 'StageCraft.Sketch.Add Fixture -4:4',
	'StageCraft.Sketch.Add Fixture 0:-3', 'StageCraft.Sketch.Add Fixture 0:0', 'StageCraft.Sketch.Add Fixture 0:3',
	'StageCraft.Sketch.Add Fixture 2:-3', 'StageCraft.Sketch.Add Fixture 2:0', 'StageCraft.Sketch.Add Fixture 2:3'
) $VenueLook

# Conference: a 3 x 6 m riser at 0.4 m and one front truss at 4.5 m, in the studio.
$Steps += Stage 35 'Conference' @(
	'StageCraft.Sketch.Set DeckHeight 40', 'StageCraft.Sketch.Set TrussHeight 450',
	'StageCraft.Sketch.Add Shape -1.5:-3 1.5:-3 1.5:3 -1.5:3 closed',
	'StageCraft.Sketch.Add Truss -4:-4 -4:4',
	'StageCraft.Sketch.Add Fixture -4:-3', 'StageCraft.Sketch.Add Fixture -4:-1', 'StageCraft.Sketch.Add Fixture -4:1', 'StageCraft.Sketch.Add Fixture -4:3'
) @('StageCraft.Environment.Atmosphere Minimalist Studio')

# Empty Stage: a clear floor in daylight.
$Steps += Stage 50 'Empty Stage' @() @('StageCraft.Environment.Atmosphere Clear Daytime')
$Steps += '62 quit'

& (Join-Path $Root 'Scripts\Tests\RunGameScripted.ps1') -Name 'StarterStages' -Steps $Steps -Extra '-StageNoWelcome' -TimeoutSeconds 300 `
	-CollectScenes 'Concert', 'Theatre', 'Conference', 'Empty Stage' -CollectTo $Templates
